import pandas as pd
import numpy as np
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
from pymatgen.analysis.structure_matcher import StructureMatcher

df = pd.read_csv('cdft_piezo_pool.csv')

print("=== Distortion from higher symmetry / inversion ===\n")

for i, row in df.iterrows():
    s = Structure.from_str(row['poscar'], fmt='poscar')
    # try multiple symprec to see if higher symmetry appears
    sgs = {}
    for prec in [0.01, 0.05, 0.1, 0.2, 0.3, 0.5, 1.0]:
        try:
            sga = SpacegroupAnalyzer(s, symprec=prec)
            sgs[prec] = (sga.get_space_group_symbol(), sga.get_space_group_number(), sga.get_point_group_symbol())
        except:
            sgs[prec] = ('err',0,'?')

    # unique sequence
    seq = []
    for prec in [0.01, 0.05, 0.1, 0.2, 0.3, 0.5, 1.0]:
        val = sgs[prec][0]
        if not seq or seq[-1][1] != val:
            seq.append((prec, val, sgs[prec][2]))

    # only print if it jumps to centro or higher at loose prec
    centro_at = None
    for prec in [0.01, 0.05, 0.1, 0.2, 0.3, 0.5, 1.0]:
        pg = sgs[prec][2]
        # laue / centro pgs
        centro_pgs = {'-1','2/m','mmm','4/m','4/mmm','-3','-3m','6/m','6/mmm','m-3','m-3m'}
        if pg in centro_pgs:
            centro_at = prec
            break

    flag = ""
    if centro_at is not None and centro_at <= 0.5:
        flag = f" ** NEAR-CENTRO at symprec={centro_at}"
    if len(seq) > 1:
        print(f"{row['candidate_id']:5s} {row['formula']:16s} {seq}{flag}")
    elif flag:
        print(f"{row['candidate_id']:5s} {row['formula']:16s} {seq}{flag}")
